// Some portions generated by Co-Pilot
import { Link } from "@/i18n/navigation";
import { getLocale, getTranslations } from "next-intl/server";
import { FiArrowUpRight } from "react-icons/fi";
import { getNewsPageData } from "@/utils/news";
import { formatDate } from "@/utils/date";

const LatestNews = async () => {
  const [t, locale, { posts }] = await Promise.all([
    getTranslations("LatestNews"),
    getLocale(),
    getNewsPageData({ numPosts: 4 }),
  ]);

  return (
    <section className="bg-purple py-16 text-white sm:py-20">
      <div className="mx-auto max-w-7xl px-6 sm:px-8">
        <div className="mb-9 flex flex-col justify-between gap-5 sm:flex-row sm:items-end">
          <div className="max-w-2xl">
            <p className="mb-3 font-mono text-xs tracking-[0.2em] text-[#ff91b7]">
              ECLIPSE ADOPTIUM
            </p>
            <h2 className="mb-3 text-3xl font-semibold leading-tight tracking-tight sm:text-4xl">
              {t("latest-news-and-updates")}
            </h2>
            <p className="mb-0 text-sm leading-relaxed text-grey">
              {t("subtitle")}
            </p>
          </div>
          <Link
            href="/news"
            className="inline-flex shrink-0 items-center gap-2 text-sm text-grey hover:text-white focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-pink"
          >
            <span>{t("see-all-news")}</span>
            <FiArrowUpRight aria-hidden="true" />
          </Link>
        </div>

        <div className="grid gap-4 lg:grid-cols-2">
          {posts.map((post, index) => {
            const featured = index === 0;
            const titleId = `latest-news-${index}`;
            return (
              <article
                key={post.slug}
                className={featured ? "lg:row-span-3" : ""}
              >
                <Link
                  href={`/news/${post.year}/${post.month}/${post.slug}`}
                  aria-labelledby={titleId}
                  className={`group flex h-full flex-col rounded-2xl border border-white/10 transition-colors hover:border-pink/40 hover:bg-white/5 focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-pink ${
                    featured
                      ? "bg-gradient-to-br from-[#7026b9]/15 via-white/[0.03] to-pink/5 p-7 sm:p-8"
                      : "bg-white/[0.02] p-5 sm:p-6"
                  }`}
                >
                  <div className="mb-3 flex items-center justify-between gap-3">
                    <time
                      dateTime={post.metadata.date}
                      className={`font-mono text-xs ${featured ? "text-[#ff91b7]" : "text-grey"}`}
                    >
                      {formatDate(post.metadata.date, locale)}
                    </time>
                    {!featured && (
                      <FiArrowUpRight
                        aria-hidden="true"
                        size={20}
                        className="shrink-0 text-[#ff91b7] transition-colors group-hover:text-white"
                      />
                    )}
                  </div>
                  <h3
                    id={titleId}
                    className={`mb-0 font-semibold leading-snug tracking-tight text-white ${
                      featured ? "text-2xl sm:text-3xl" : "text-base sm:text-lg"
                    }`}
                  >
                    {post.metadata.title}
                  </h3>
                  {featured && (
                    <p className="mb-8 mt-4 line-clamp-3 text-sm leading-relaxed text-grey">
                      {post.metadata.description}
                    </p>
                  )}
                  {featured && (
                    <div className="mt-auto flex items-center justify-between border-t border-white/10 pt-5">
                      <span className="text-sm">{t("read-more")}</span>
                      <FiArrowUpRight
                        aria-hidden="true"
                        className="text-[#ff91b7] transition-colors group-hover:text-white"
                        size={20}
                      />
                    </div>
                  )}
                </Link>
              </article>
            );
          })}
        </div>
      </div>
    </section>
  );
};

export default LatestNews;
